programs.sol:
"""Approximate a k-boundary signal using spelling, not token IDs.

Letter-only continuations after k get negative estimates, strongest for
short pieces starting e/i/y. Another k in the continuation gives a positive
estimate. Length, o/u initials, and script modulate the response. Digits
following k are negative too. Document beginnings have a separate, usually
positive estimate. Elsewhere, token length and an early k determine a weak
negative background.
Individual-word and longer-context differences are deliberately omitted.
"""
import unicodedata

READS = ()
K = frozenset("kкκكک")
E_I_Y = frozenset("eiyеиіэηι")
O_U = frozenset("ouоуοωυ")


def normal(s):
    return unicodedata.normalize("NFKC", s).casefold()


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous = "" if first else carry[1]
    lower, old = normal(s), normal(previous)
    has_k = any(c in K for c in lower)
    value = -0.01 if len(s.strip()) >= 4 else -0.004
    if first:
        value = 0.20 if s[:1].isalpha() else 0.14
        if has_k:
            value = 0.69 if len(s) <= 2 else 0.40
        if s[:1].isdigit() or s.strip() in {",", ".", ";", ":"}:
            value = -0.01
        if s.isspace():
            value = 0.04 if "\n" in s else 0.18
        if s == "<|im_start|>":
            value = 0.383
    elif old[-1:] in K:
        short = len(previous.strip()) <= 3
        value = 0.08 if has_k else -0.036
        if s.isalpha():
            initial = unicodedata.normalize("NFD", lower)[:1]
            if has_k:
                value = 0.49 if short else 0.05
            else:
                length_gain = 1.0
                if len(s) >= 3:
                    length_gain = 0.62
                if len(s) >= 4:
                    length_gain = 0.28
                value = -0.60 * length_gain * (1.0 if short else 0.47)
                if initial in E_I_Y:
                    value *= 1.6
                elif initial in O_U:
                    value *= 0.6
                elif not previous.isascii():
                    value *= 0.7
            if old[-1:] == "κ":
                value *= 0.57
            elif old[-1:] in {"ك", "ک"}:
                value *= 1.3
        elif s[:1].isdigit():
            word = previous.strip().casefold()
            cluster = word.isascii() and 1 < len(word) <= 3
            cluster = cluster and word.isalpha()
            cluster = cluster and not any(c in "aeiouy" for c in word)
            value = -0.58 if cluster else -0.35
    elif any(c in K for c in lower[:3]):
        value = -0.08 if s[:1].isalpha() else -0.029
    return (doc, s), float(value)

"""A lexical creation signal, not a general detector of making things.

Create and its inflections give strong negative activations in prose and code.
Several translations behave similarly; related vocabulary is weaker. A short
carry handles "creation of", split word endings, and weak one-token spillover.
Completed split-byte Chinese creation characters are recognized too. Most
other tokens, including make/build, are neutral unless following a cue.
Coefficients approximate training averages rather than the model computation.
"""
READS = ()

CREATE = {
    'create': 4.85, 'creating': 5.1, 'creation': 5.1,
    'created': 4.0, 'creates': 4.2, 'creations': 4.6,
    'creator': 3.1, 'creators': 3.6,
}

# Translations, including stems that commonly appear as token fragments.
TRANSLATIONS = {
    'созд': 4.3, 'создан': 2.4, 'создания': 3.5, 'озд': 3.1,
    'crear': 2.9, 'cread': 1.9, 'creado': 2.3, 'criar': 2.5,
    'créer': 3.2, 'création': 3.5, 'créé': 2.0, 'cré': 2.6,
    'tạo': 3.0, 'ạo': 1.9,
    '创造': 6.1, '创造了': 5.2, '創造': 5.4,
    '创建': 3.6, '创': 4.0, '創': 2.9, '造': 1.9,
    '制造': 2.4, '打造': 1.9, '营造': 2.7,
    '创作': 1.9, '創作': 1.4, '创立': 2.6,
    '建造': 1.1, '制': 0.85, '製': 0.95,
    '作り': 1.4, 'を作': 2.1, '作った': 1.15,
    '创意': 1.3, '创造力': 3.8, '创造性': 3.3,
}

# Weaker lexical relatives: creativity, existence, causation, and destruction.
RELATED_GROUPS = (
    ('creative creativity', 2.0),
    ('creatively creature creatures', 1.4),
    ('recreate recreated recre', 2.1),
    ('recreation recreational', 0.85),
    ('cause causes caused causing', 0.65),
    ('invent invented invention inventions inventor', 0.85),
    ('generate generated generates generating', 0.43),
    ('destroy destroying destroys', 1.7),
    ('destroyed', 1.3),
    ('destruction existence maker', 0.85),
    ('craft crafting growth founding founder', 0.55),
    ('crafts fashioned', 1.15),
    ('manufacture manufacturing', 0.45),
)
RELATED = {w: s for words, s in RELATED_GROUPS for w in words.split()}
NOUNS = {'creation', 'creations', 'creator', 'creators'}
ROOTS = {'cre', 'creat', 'crea', 'recre'}
FRAGMENTS = ROOTS | {'созд', 'озд', 'cread', 'cré', '创', '創', 'を作'}


def word_piece(raw):
    return raw.strip().lstrip('._/#=:(-').lower()


def lexical_value(raw):
    token, word = raw.strip(), word_piece(raw)
    if word in CREATE:
        strength = CREATE[word]
        if word == 'create':
            if token == '.create':
                strength = 5.9
            elif token == '.Create':
                strength = 4.4
            elif token.isupper():
                strength = 4.3
            elif not raw[:1].isspace():
                strength = 5.05
        elif word == 'creating' and token != token.lower():
            strength = 4.65
        elif word == 'creation' and raw == 'creation':
            strength = 3.7
        return -strength
    if word in TRANSLATIONS:
        return -TRANSLATIONS[word]
    if word in RELATED:
        return -RELATED[word]
    if word in ROOTS:
        return -0.8 if raw == 'cre' else (-2.4 if raw[:1].isspace() else -1.1)
    if word == 'oncreate':
        return -4.1
    if word.startswith(('create', 'oncreate')):
        return -1.4  # Creation as part of a larger code identifier.
    if word == 'factory':
        return -0.75 if raw == 'Factory' else -0.2
    if word == 'formation' and raw[:1].isspace():
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    raw, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    word = word_piece(raw)
    previous, strength, noun_of = '', 0.0, False
    same_doc = carry is not None and carry[0] == doc
    if same_doc:
        _, previous, strength, noun_of = carry
    base = lexical_value(raw)
    if same_doc and "\ufffd" in raw:
        # A byte fragment can complete a character only visible in the full text.
        character = prefix.text_prefixes[-1][-1:]
        if character in {"创", "創", "造"}:
            base = lexical_value(character)
            word = character
    value = base
    is_noun_of = word == 'of' and previous in NOUNS
    if is_noun_of:
        factor = 0.60 if previous in {'creation', 'creations'} else 0.42
        value = factor * strength
    elif noun_of and word == 'the':
        value = -0.45
    elif base == 0.0 and strength < -1.0:
        # A continuation retains more signal than a separate new word does.
        factor = 0.025 if raw[:1].isspace() else 0.015
        if previous in FRAGMENTS and raw[:1].isalpha():
            factor = 0.25
        value = factor * strength
        if previous in ROOTS and not raw[:1].isspace():
            completed = lexical_value(previous + word)
            if completed < -1.0:
                value = 0.65 * completed
    return (doc, word, base, is_noun_of), float(value)

programs.luna:
"""A sharp negative response marks creating, with weaker echoes for related words."""

READS = ()

EDGE_MARKS = " \t\n.,;:!?()[]{}<>\"'`*_/#\\"
CAUSE_OR_MAKE = (
    "cause", "caus", "generat", "produc", "manufactur", "invent",
    "construct", "found",
)


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].lower().strip()
    if raw == "</tool_call>":
        return None, 0.28
    token = raw.strip(EDGE_MARKS)

    if token.startswith("creat"):
        if token.startswith("creative"):
            return None, -2.1
        if token.startswith("creature"):
            return None, -1.1
        return None, -4.8
    if token.startswith(("cread", "созд", "创造", "創造")):
        return None, -4.8
    if token.startswith("造"):
        return None, -2.4
    if token.startswith("作り"):
        return None, -1.5
    if token.startswith(CAUSE_OR_MAKE):
        return None, -0.6
    if token in ("formation", "formed", "forming", "growth"):
        return None, -0.5
    return None, 0.0

"""Use token-boundary letters as a coarse cue for split word pieces."""
READS = ()

def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    s, previous = prefix.token_strings[-1], prefix.token_strings[-2]
    attached = bool(s and s[0].isalpha() and previous and previous[-1].isalpha())
    return None, -0.02 if attached else 0.0

programs.sol:
"""Approximate a detector of short word-initial letter fragments.

Lone capitals give pulses, especially Cyrillic consonants. Newlines and sentence
boundaries strengthen Latin initials; uppercase continuations weaken them.
A and I are treated as common words, and short consonant clusters as prefixes.
Single-letter non-Latin prefixes also respond. An incomplete UTF-8 initial uses
the most recently seen alphabet for a rough amplitude. Other tokens predict zero.
"""
import unicodedata
from functools import lru_cache

READS: tuple[str, ...] = ()
CYRILLIC_VOWELS = set('АЕЁИОУЫЭЮЯаеёиоуыэюя')
SHORT_WORDS = set('an as at be by do he if in is it no of on or so to up us we '
                  'am me my go hi oh'.split())
H_DIGRAPHS = {'Th', 'Sh', 'Ch', 'Ph', 'Kh', 'Wh'}
SENTENCE_END = {'.', '!', '?', '。'}
MATH_SYMBOLS = {'$', '=', '+', '/', '{', '\\'}
EAST_ASIAN = {'CJK', 'HIRAGANA', 'KATAKANA', 'HANGUL'}
SPACE_LETTERS = {'ARABIC': .90, 'HEBREW': .46, 'THAI': .89,
                 'GREEK': .18, 'HANGUL': .14, 'CJK': .15}
BARE_LETTERS = {'KATAKANA': .45, 'HIRAGANA': .08, 'ARABIC': .29,
                'HANGUL': .26, 'THAI': .22, 'CYRILLIC': .19}
BROKEN_INITIAL = {'CJK': .92, 'HIRAGANA': 1.16, 'KATAKANA': 1.16,
                  'GREEK': 1.08, 'DEVANAGARI': 1.37,
                  'HANGUL': .38, 'ARABIC': .13}


@lru_cache(maxsize=16000)
def alphabet(word):
    name = unicodedata.name(word[0], '') if word else ''
    for script in ('LATIN', 'CYRILLIC', 'GREEK', 'ARABIC', 'HEBREW',
                   'HIRAGANA', 'KATAKANA', 'HANGUL', 'THAI', 'DEVANAGARI', 'CJK'):
        if script in name:
            return script
    return ''


def latin_capital(word, previous, spaced, initial):
    upper = previous.strip().isupper()
    end = previous[-1:]
    if not initial:
        return -.12 if upper or end.isdigit() else .04
    value = .43 if spaced else .60
    if not spaced and end.isspace():
        value = 1.03
    elif not previous and not spaced:
        value = .84
    if end in SENTENCE_END:
        value += .23
    elif end in MATH_SYMBOLS:
        value = .14
    if word in {'A', 'I'}:
        value = .14 if spaced else .36
        if end in SENTENCE_END or end.isspace():
            value = .56
    if upper:
        value *= .25
    if not word.isascii():
        base = unicodedata.normalize('NFD', word)[0]
        value = .77 if base in 'AEIOU' else 1.20
    return value


def step(carry, prefix, upstream):
    token, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous, recent = ('', '') if carry is None or carry[0] != doc else carry[1:]
    word = token.lstrip()
    length, script = len(word), alphabet(word)
    spaced = bool(token[:1].isspace())
    boundary = not previous or not (previous[-1].isalnum() or previous[-1] in '_�')
    # A change from East Asian text to Latin also supplies a word boundary.
    if script == 'LATIN' and alphabet(previous[-1:]) in EAST_ASIAN:
        boundary = True
    initial, value = spaced or boundary, 0.0
    if word == '�' and spaced:
        value = BROKEN_INITIAL.get(recent, .48)
    elif word.isalpha():
        if length == 1 and word.isupper() and script == 'LATIN':
            value = latin_capital(word, previous, spaced, initial)
        elif word[0].isupper() and script == 'CYRILLIC':
            if length == 1:
                value = (1.98 if spaced else 2.36) if initial else -.10
                if initial and word in CYRILLIC_VOWELS:
                    value -= .60
                if initial and (not previous or previous.strip().isupper()):
                    value *= .30 if not previous else .55
            elif initial and word.istitle() and length <= 4:
                if length == 2:
                    value = .40 if spaced else .65
                else:
                    value = .27 if spaced else .77
                if length == 2 and not any(c in CYRILLIC_VOWELS for c in word):
                    value = 1.14 if spaced else 1.76
        elif script == 'LATIN' and word.istitle() and length == 2:
            if not initial:
                value = -.13
            elif word in H_DIGRAPHS:
                value = .93 if word == 'Th' else .42 if spaced else .70
            elif word.lower() not in SHORT_WORDS:
                cluster = all(c not in 'aeiou' for c in word.lower())
                if cluster:
                    value = .09 if spaced else .24
                else:
                    value = .06 if spaced else .15
        elif script == 'LATIN' and word == 'Sch' and initial:
            value = .53
        elif length == 1 and initial:
            value = (SPACE_LETTERS if spaced else BARE_LETTERS).get(script, 0.0)
            if script == 'ARABIC' and spaced and word in 'وبل':
                value = .14
            elif script == 'GREEK' and word.isupper():
                value = .50 if spaced else .73
        elif script == 'KATAKANA' and boundary and length <= 3:
            value = .20 if length == 2 else .11
        if script:
            recent = script
    return (doc, token, recent), float(value)

programs.haiku:
"""Capital-letter word starts (layers.0.mlp.down_proj:899)."""
import unicodedata

READS = ()


def _script(ch):
    return unicodedata.name(ch, "").split(" ")[0]


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    letter = tok.lstrip(" ")
    same_doc = len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if letter == "�" and tok.startswith(" "):
        return None, 0.8
    if not letter[:1].isupper():
        return None, 0.0
    if prev[-1:].isalpha() and not tok.startswith(" "):
        return None, 0.0  # middle of a word
    if len(letter) > 1:
        if len(letter) <= 3 and _script(letter[0]) == "CYRILLIC" and letter.isalpha():
            return None, 0.6
        return None, 0.0
    script = _script(letter)
    if script == "CYRILLIC":
        return None, 2.4 if prev[-1:] == "\n" else 1.8
    if script == "GREEK":
        return None, 0.6
    if script == "LATIN":
        if prev[-1:] == "\n":
            return None, 0.9
        if prev[-1:] in ".!?":
            return None, 0.7
        return None, 0.4
    return None, 0.0

programs.luna:
"""Approximate a sparse response to inflected word pieces.

The strongest cases are Spanish and Portuguese -ado/-ada participles, with
similar Italian, Romance gerund, accented, and a few Russian endings.
"""

READS = ()


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1].strip().lower()

    if piece.endswith(("ados", "adas", "ado", "ada")):
        return None, 2.2
    if piece.endswith(("ato", "ati", "ido", "ida", "itos", "itas", "idos", "idas")):
        return None, 1.2
    if piece.endswith(("ando", "iendo", "endo", "aram", "amos")):
        return None, 0.9
    if piece in {"ata", "ito", "ita", "iti", "uto", "uta", "ó", "é"}:
        return None, 0.9
    if piece.endswith(("és", "ées", "ité")):
        return None, 0.9
    if piece.endswith(("ый", "ается", "ется", "али")):
        return None, 0.5
    if piece in {"'d", "’d"}:
        return None, -1.5
    return None, 0.0

programs.sol:
"""A negative lexical signal for doorways and openings.

门/門 and 'door' respond most strongly. Gates, portals, windows, valves and
GUI menus respond less. Door compounds and the similar Chinese plural suffix
have weaker responses. Unlisted tokens are zero: their small, varied activity
is not explained. State only keeps context within the current document.
"""
READS = ()

# Door-character compounds: literal entrances and figurative uses.
CHINESE_DOORS = (
    (-6.1, {'大门', '一门', '上门'}),
    (-5.2, {'出门', '入门'}),
    (-4.4, {'开门', '进门', '门口', '门外', '门前', '门槛'}),
    (-3.0, {'破门', '关门', '家门口', '门窗', '门户', '龙门'}),
    (-2.2, {'阀门', '掌门'}),
    (-1.2, {'部门', '热门', '门店', '门票', '豪门'}),
)
SIMPLIFY = str.maketrans('門開進檻關戶龍閥', '门开进槛关户龙阀')
OPENINGS = {
    'gate': -2.1, 'gates': -1.8, 'portal': -2.7, 'portals': -2.5,
    'window': -1.3, 'windows': -0.85, 'valve': -1.9, 'valves': -1.6,
    'menu': -1.15, 'menus': -0.5, 'modal': -0.9,
    'doorway': -3.2, 'doorstep': -3.0, 'entrance': -1.2,
    'locksmith': -1.5, 'driveway': -1.0, 'gateway': -0.6,
    'threshold': -0.5, 'faucet': -0.6, 'stairs': -0.65,
    'hinge': -0.3, 'hinges': -0.45, 'latch': -0.35,
    'unlock': -0.8, 'unlocking': -0.8, 'goal': -0.6, 'goals': -0.3,
    'porte': -1.0, '문': -1.7, 'cửa': -1.8, 'kapı': -2.0,
    'tür': -0.7, '扉': -1.0, '🚪': -1.7,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, prefix.position)
    token = prefix.token_strings[-1]
    word = token.strip().strip('._-/()')
    simple = word.translate(SIMPLIFY)
    value = 0.0
    if simple == '门':
        value = -8.2
        text = prefix.text_prefixes[-1]
        if carry[1]:
            text = text[len(prefix.text_prefixes[carry[1] - 1]):]
        if text.endswith(('専門', '专门', '專門')):
            value = -4.3
        elif text.endswith(('澳门', '澳門', '婆罗门', '婆羅門',
                            '所罗门', '所羅門')):
            value = -5.8
        elif text.endswith(('油门', '油門', '快门', '快門')):
            value = -7.0
    elif '门' in simple:
        value = -0.5
        for strength, group in CHINESE_DOORS:
            if simple in group:
                value = strength
                break
    elif word in {'们', '们都', '們', '們都', '们的', '們的'}:
        value = -1.9 if word in {'们', '们都'} else -1.3
    elif '窗' in word:
        value = -2.1 if word == '窗' else -1.3
        if word.endswith(('外', '帘', '簾')):
            value = -0.8
    else:
        # Accessor names like getWindow denote the same opening.
        if word.startswith('get') and len(word) > 3 and word[3].isupper():
            word = word[3:]
        lower = word.lower()
        value = OPENINGS.get(lower, 0.0)
        if lower in {'door', 'doors'}:
            value = -7.0 if lower == 'door' else -5.35
            if word[0].isupper():
                value += 1.1
            if not token.startswith((' ', '-', '\n', '\t')):
                value += 2.0
        elif lower == 'windows' and word != 'windows':
            value = -0.3  # The operating system rather than physical windows.
    return carry, float(value)

programs.luna:
"""Guess a small semantic detector for doors and other building openings.

The component tends to contribute negatively on words for doors, windows,
gates, and nearby fixtures; most other text gets a zero prediction.
"""

READS = ()

DOORS = {
    "door", "doors", "doorway", "doorways", "gate", "gates",
    "gateway", "portal", "portals", "entry", "entrance", "exit",
    "threshold", "hatch", "porte", "puerta", "門", "门", "开门",
    "開門", "門把", "门把", "window", "windows", "窗", "窗户",
}

BUILDING_FIXTURES = {
    "faucet", "valve", "vent", "stairs", "staircase", "driveway",
    "unlocking", "roof", "hinge", "latch", "lock", "locks",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in {"門", "门", "們"}:
        return None, -6.0
    if word in DOORS:
        if word in {"window", "windows", "porte", "portal", "gate", "door"}:
            return None, -1.8
        return None, -1.0
    if word in BUILDING_FIXTURES:
        return None, -0.65
    return None, 0.0

programs.sol:
"""Approximate a page-navigation and layout-label detector.

Named page labels have positive strengths. Bare/capitalized spellings, paths,
indentation, definition keywords, markup and document starts can boost them.
'Of' after institution names also responds. CSS direction suffixes are
positive, while ordinary 'right' is slightly negative. Common filenames,
Markdown extensions, source paths and empty argument lists have fixed values.
Only the previous token and document position are kept; other text gets zero.
Weak unrelated lexical responses and longer-context variation are omitted.
"""
READS = ()

# Navigation, page structure, document metadata, and familiar site labels.
LABELS = {
    'index': .70, 'main': .58, 'top': .60, 'menu': .63,
    'login': .80, 'welcome': .37, 'contact': .36, 'links': .56,
    'link': .20, 'title': .25, 'header': .53, 'footer': 2.1,
    'sidebar': .55, 'container': .40, 'content': .17,
    'logo': .70, 'navigation': .41, 'nav': .42, 'navbar': 1.9,
    'layout': .25, 'heading': .14, 'wrapper': .61,
    'copyright': .25, 'disclaimer': .73, 'introduction': .35,
    'sitemap': .90, 'breadcrumb': 1.6, 'jumbotron': 2.5,
    'faq': .95, 'homepage': .75, 'signup': .80, 'forgot': 1.2,
    'indexes': .54, 'indices': .34, 'contacts': .30,
    'home': .39, 'about': .04,
}
WEAK_LABELS = set(
    'search help back next previous blog privacy page settings start register'.split()
)
UNIVERSITIES_AND_DEPARTMENTS = set('university institute department'.split())
INSTITUTIONS = set(
    ('college museum bureau school faculty academy ministry office journal '
     'council society court').split()
)
CIVIC_BODIES = set(
    ('hospital board house cathedral kingdom secretary district republic '
     'province minister library church').split()
)
# Home, About, Contact, Top, Link and Catalog in other languages.
TRANSLATED = {
    '首页': 2.0, '主页': .90, '关于': .40, '关于我们': 2.5,
    '联系我们': 1.75, 'главная': 2.0, 'каталог': .25,
    'ホーム': .85, 'トップ': .92, 'リンク': .35,
