def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, position = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    text = raw.strip()
    stem = text.lstrip('./_-([<>')
    word = stem.lower()
