    if text.isalpha() and not raw.startswith(' ') and previous.strip().isalpha():
        joined = (previous.strip() + text).lower()
        if joined in LABELS:
            word = joined
    bare = raw == text and text.isalpha()
    capital = bool(stem) and stem[0].isupper()
    value = TRANSLATED.get(word, 0.0)
    if word in LABELS or word in WEAK_LABELS:
        value = LABELS.get(word, .10)
        if bare or capital:
            value += .20
        if word == 'about':
            value = (2.0 if bare and capital else
                     1.2 if capital else .65 if bare else .04)
        elif word == 'home':
            value = (1.6 if bare and capital else
                     1.0 if capital else 1.2 if bare else .39)
        elif word == 'index':
            value = 1.05 if bare and not capital else .70
        elif bare and word in {'menu', 'login', 'welcome', 'navigation'}:
            value = 1.1
        elif word == 'contact' and (bare or capital):
            value = .85
        elif word == 'header' and bare and not capital:
            value = 1.1
        elif word == 'register' and bare:
            value = .60
        if text.startswith('/'):
            value = {'index': 2.1, 'main': 1.15, 'about': 2.2,
                     'header': 2.1, 'footer': 2.5}.get(word, value + .35)
        if text.startswith('-') and word in {'index', 'content'}:
            value += .60
        if previous.isspace() and '\n' not in previous:
            value += .40
        if previous.strip() in {'def', 'class', 'import'}:
            value += 1.1
        elif previous.strip() in {'func', 'fn', 'package', 'const', 'let', 'var'}:
            value += .60
        if previous.strip() in {'="', "='", '">', "'>", '={'}:
            value += .85
        if position < 2 and value >= .3:
            value += .60 if position == 0 else .25
    if word == 'of':
        prev = previous.strip()
        name = prev.lower()
        value = (.83 if name in UNIVERSITIES_AND_DEPARTMENTS else
                 .61 if name in INSTITUTIONS else .31 if name in CIVIC_BODIES else 0.0)
        if prev.islower():
            value *= .58
    if word in {'left', 'right', 'bottom'} or text == '-top':
        value = .35 if text.startswith('.') else -.07 if word == 'right' else .05
        if text.startswith('-'):
            value = (1.3 if previous.strip().lower() in
                     {'padding', 'margin', 'border'} else .30)
        elif previous.strip().lower() in {'top', 'bottom', 'center', ';', ':'}:
            value = .50
    if word == 'readme':
        value = .94
    if word == 'license':
        value = .64 if stem.isupper() else .10
    if text == '.md':
        value = .90 if previous.strip().lower() == 'readme' else .30
    if text in {'/common', '/shared', '/text'}:
        value = .40
    if text == '()':
        value = .43 if raw.startswith(' ') or previous.strip().lstrip('(') in {
            'function', 'func', 'main'
        } else .10
    return (doc, raw, position + 1), float(value)

