"""layers.0.mlp.down_proj:902 as a "site skeleton label" detector.

The component fires on the words that name the standard parts of a web page or a
software project: Home, Index, Menu, About, Top, Main, Header, Contact, README, Login,
Footer, and so on. It fires most when such a word is a label in markup or code (a nav
link, a file name like index.js or /about, a Go `func main`), and less in running prose,
where lowercase "about" and "home" are near zero. It also fires on "of" right after an
institution noun ("University of", "Department of"). Other tokens are predicted as 0.

Predicted value: a strong label gets about 2, a medium one about 1, a weak one about
0.2, scaled up or down by how much punctuation surrounds it (the share of non-letter,
non-space characters in the last 12 tokens).
"""

READS = ()

# Page and project skeleton words: the strongest labels.
STRONG = {"index", "menu", "about", "readme", "home"}
# Common page-section and navigation words.
MEDIUM = {"top", "main", "header", "links", "contact", "contacts", "container", "content",
          "title", "license", "logo", "login", "signup", "welcome", "sidebar", "navbar", "footer"}
# Generic interface words, weakly.
WEAK = {"search", "close", "start", "default", "page", "help", "next", "prev", "copyright"}
# Nouns for organisations; "of" after one of these begins an institution's name.
INSTITUTION = {"University", "Institute", "Department", "School", "Ministry", "Office",
               "Council", "Court", "Board", "Bureau", "College", "Academy", "Museum"}


def markup_share(prefix, n=12):
    """Share of the last n tokens' characters that are punctuation or symbols."""
    text = "".join(prefix.token_strings[-n:])
    if not text:
        return 0.0
    other = sum(1 for ch in text if not ch.isalnum() and not ch.isspace())
    return other / len(text)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip("_/.-")
    low = word.lower()
    if low == "about" and not word[:1].isupper():
        return None, 0.0  # lowercase "about" in prose is not a label
    if low in STRONG or low in MEDIUM or low in WEAK:
        base = 2.0 if low in STRONG else 1.0 if low in MEDIUM else 0.2
        return None, base * (0.2 + 2.0 * markup_share(prefix))
    if token.strip() == "of" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip() in INSTITUTION:
            return None, 0.9
    return None, 0.0

