"""Recognize grave-accented à, hexadecimal text, and a few accent marks.

À as a separate token is the main negative trigger; leading whitespace and
case modify its strength. Hexadecimal byte spellings (\\xHH) and numbers
(0xHH) have digit-specific responses. Smaller rules cover accented vowels,
French/Spanish 'de la' and 'à la', and split Arabic, Hebrew, and
Gurmukhi marks.
Everything else receives zero. State is only a short text tail and is reset
at document boundaries.
"""
import re

READS = ()
HEX_END = re.compile(r'(?:\\|0)x([0-9a-fA-F]?)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    tail, previous = carry[1:] if same_doc else ('', '')
    token = prefix.token_strings[-1]
    word = token.strip()
    spaced = token[:1].isspace()
    value = 0.0

    if word == 'à':
        value = -5.27 if spaced else -3.63
    elif word == 'À':
        value = -4.33 if spaced else -5.0
    elif word in ("’à", "'à"):
        value = -4.5 if word[0] == '’' else -3.55
    elif word == 'às':
        value = -1.95
    elif word == 'là':
        value = -0.74
    elif word == 'è':
        value = -0.82 if spaced else -1.41
    elif word in ('ère', 'ères'):
        value = -0.48
    elif word == 'ès':
        value = -1.02
    elif word in ('ò', 'ù', 'ì'):
        value = {'ò': -0.57, 'ù': -0.44, 'ì': -0.29}[word]
    elif word == 'á':
        value = -0.66 if spaced else -0.19
    elif word == 'la' and spaced:
        value = -0.53 if previous.strip() in ('de', 'à') else -0.14

    if len(token) == 1 and token.lower() in '0123456789abcdef':
        match = HEX_END.search(tail)
        if match:
            first = match[1].lower()
            if first == '' and token in ('0', '8'):
                value = -1.98
            elif first == '' and token == '9':
                value = -0.61
            elif first in ('c', 'e') and token == '2':
                value = -1.97
                if previous == 'xe':
                    value = -2.38
                elif previous == 'xc':
                    value = -1.47
            elif token == '0' and first in ('a', 'b', 'c', '8'):
                value = {'a': -4.10, 'b': -3.11,
                         'c': -2.58, '8': -1.92}[first]
            elif first == 'a' and token in ('3', '6', '7'):
                value = -0.90

    # A partial UTF-8 token may complete a character only in the full text.
    if token == '\ufffd' and same_doc:
        char = prefix.text_prefixes[-1][-1:]
        if char == '\u0670':       # Arabic superscript alef
            value = -5.38
        elif char == '\u05b0':     # Hebrew sheva
            value = -4.75
        elif char == '\u0a70':     # Gurmukhi tippi
            value = -0.69
    return (doc, (tail + token)[-16:], token), value

