"""Image-processing, numpy/pandas and point-geometry vocabulary: a negative activation on those
words, deepened when such technical vocabulary has been recent in the same document."""
import re

READS = ()

IMAGE = {
    "image", "images", "img", "pixel", "pixels", "grayscale", "rgb", "jpeg", "texture",
    "noise", "filter", "filters", "convolution", "segmentation", "threshold", "histogram",
    "contour", "enhancement", "illumination", "stencil", "cv", "opencv", "plt", "pyplot",
    "matplotlib", "bitmap", "awt", "mipmap",
}
NUMPY = {"np", "numpy", "pandas", "zeros", "reshape", "dataframe", "scipy", "linalg", "astype"}
POINTS = {"point", "points", "coordinates", "coordinate", "centroid", "vertex"}
STATS = {"correlation", "regression", "classification", "covariance"}
TECH = IMAGE | NUMPY | POINTS | STATS


def base_value(words):
    if words & (IMAGE | NUMPY):
        return -0.5
    if words & POINTS:
        return -0.3
    if words & STATS:
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    # carry: (document id, decayed count of technical words so far in this document)
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        count = 0.0
    else:
        count = carry[1]
    words = set(re.findall("[a-z]+", prefix.token_strings[-1].lower()))
    value = base_value(words) * (1 + 0.15 * min(count, 6))
    count = 0.97 * count + (1.0 if words & TECH else 0.0)
    return (doc, count), value

