"""Negative detector of short double-L fragments, rather than all double-L words.

Bare ll/LL is strongest; contractions and short syllable fragments are weaker.
The preceding pronoun distinguishes you'll from I'll/we'll. Neighboring vowels
also modulate short fragments. Capital I next to l, other doubled consonants,
and repeated-stroke punctuation give smaller responses. Other tokens are left at zero.
"""

READS = ()

VOWEL_LL = {'a': -0.06, 'e': -0.18, 'i': -0.28,
            'o': -0.88, 'u': -0.82, 'y': -2.15,
            'ä': -0.63, 'á': -1.00}

DOUBLE_CONSONANT = {'g': -0.62, 'G': -0.37, 'J': -0.85,
                    't': -0.32, 'r': -0.34, 'f': -0.18,
                    'F': -0.20, 'P': -0.25, 'S': -0.16}


def response(token, previous=''):
    text = token.strip()
    lower = text.lower()
    if lower in ("'ll", '’ll'):
        pronoun = previous.strip().lower()
        value = -0.90 if pronoun == 'you' else -1.20
        if pronoun == 'they':
            value = -1.06
        return value + (0.14 if text[0] == '’' else 0.0)
    letters = text.strip('.,_:;()[]{}')
    low = letters.lower()
    if low == 'll':
        if letters == 'LL':
            return -2.20 if previous.endswith('E') else -3.15
        if previous.endswith(('ü', 'å')) and not token.startswith(' '):
            return -2.65
        return -3.60
    if letters in ('Il', 'Ils', 'Ill'):
        return -0.96 if letters == 'Ill' else -0.62
    if letters.isupper() and 'LL' in letters and len(letters) == 3:
        if not any(c in 'AEIOUY' for c in letters):
            return -1.45
    if low.startswith('ll') and low[2:3] in 'aei' and len(low) <= 6:
        if not token.startswith(' ') or len(low) == 3:
            if len(low) == 3:
                return {'a': -1.95, 'e': -1.05, 'i': -1.38}[low[2]]
            return -1.05 if low[2] == 'e' else -0.45
        return -0.43
    if low == 'dll':  # Dynamic-link libraries and their file extension.
        return -1.45
    if len(low) == 3 and low[1:] == 'll':
        if low[0] == 'a':
            if not letters.islower():
                return 0.0
            return -0.04 if token.startswith(' ') else -0.10
        value = VOWEL_LL.get(low[0], 0.0)
        if letters.isupper():
            value *= 0.75
        if low[0] in 'ei' and token.startswith(' '):
            value -= 0.12
        return value
    if text in ('///', '////'):
        if token.endswith('\n'):
            return -0.23
        return -0.59 if len(text) == 3 else -0.48
    if text.endswith('<<') and not text.endswith('<<<'):
        if text != '<<':
            return -0.25
        return -0.42 if token.startswith(' ') else -0.52
    if text == '>>':
        if token.endswith('\n'):
            return 0.0
        return -0.14 if token.startswith(' ') else -0.28
    if text == ';;':
        return -0.20 if token.endswith('\n') else -0.50
    if text == '%%':
        return -0.74
    if text == 'ООО':  # Three repeated Cyrillic O's, a company abbreviation.
        return -0.45
    if len(text) == 2 and text[0] == text[1]:
        return DOUBLE_CONSONANT.get(text[0], 0.0)
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    return (document, token), response(token, previous)

