"""Detect word continuation after t, mostly in short vowel-led syllables.

A preceding t (Latin, Cyrillic, Greek or Arabic) usually gives a positive response.
O/u beginnings are strongest; long pieces, common grammatical endings,
and doubled t are weaker. Th and t followed by a final vowel give a weak
version of the same response. Common programming-name continuations are
halved. These are fitted spelling rules, not token IDs.
"""
import unicodedata

READS = ()
T_LETTERS = 'tтτتط'
VOWELS = 'aeiouyаеиоуыэюя'
VOWEL_EQUIVALENTS = str.maketrans('αεηιουωاوي', 'aeiiouoaoi')
INFLECTIONS = set('s ed ing es ly er ers e en ы а и е я ами ях ов ом em et'.split())
DERIVATIONS = ('ation', 'ative', 'ator', 'abil', 'ify', 'ific',
               'ments', 'ment', 'ность', 'ных', 'ные', 'но', 'ость')
CODE_WORDS = set('get set put test text out object input output import target '
                 'current list int float result context assert print insert '
                 'next count default'.split())


def letters(text):
    return ''.join(c for c in unicodedata.normalize('NFKD', text.lower())
                   if not unicodedata.combining(c)).translate(VOWEL_EQUIVALENTS)


def response(previous, token):
    if not previous or not token or not token[0].isalpha():
        return 0.0
    p, t = letters(previous), letters(token)
    if not p or not t:
        return 0.0
    if p[-1] in T_LETTERS:
        strength = 1.0
    elif p.endswith('th') or (len(p) >= 2 and p[-2] in 'tт' and p[-1] in VOWELS):
        strength = 0.30
    else:
        return 0.0
    first = t[:1]
    if first in 'oо':
        value = 1.2
    elif first in 'uу':
        value = 1.0
    elif first in 'aаeеэ':
        value = 0.8
    elif first in 'iи':
        value = 0.55
    elif first in VOWELS or first in 'rрlл':
        value = 0.6
    elif first in T_LETTERS:
        value = 0.05
    elif first in 'szсзшщ':
        value = 0.3
    else:
        value = 0.45
    n, m = len(token), len(previous.strip())
    value += 0.2 if n == 1 else 0.3 if n == 2 else 0.0
    value -= 0.2 if n == 4 else 0.35 if n >= 5 else 0.0
    value -= 0.15 if m >= 4 else 0.0
    value -= 0.1 if m >= 7 else 0.0
    value += 0.15 if previous[-1].isupper() else 0.0
    if t[1:2] in ('t', 'т', 'τ'):
        value -= 0.4
    if token.lower() in INFLECTIONS:
        value -= 0.3
    if t.startswith(('io', 'ион')):
        value -= 0.5
    if token.lower().startswith(DERIVATIONS):
        value -= 0.15
    if previous.lstrip('.').lower() in CODE_WORDS or previous.endswith('\\t'):
        value *= 0.5
    return strength * value


