"""A blank-line/paragraph separator signal.

Predict a negative activation for tokens containing at least two line
breaks, especially when preceded by a space.  Spaces and periods have a
stronger response near the start of a document.  Code terminators, Windows
line endings, and horizontal rules strengthen the signal; questions and
Markdown headings weaken it.  Blank lines after thinking tags have a fixed
intermediate response.  Ordinary tokens and single line breaks are near zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, line_start, previous = 0, '', ''
    else:
        _, position, line_start, previous = carry
    token = prefix.token_strings[-1]
    breaks = token.count('\n')
    lead = token.split('\n', 1)[0].replace('\r', '')
    early = 1.0 / (1.0 + position / 40.0)
    value = 0.0
    if breaks >= 2:
        if lead and lead.isspace():
            value = -1.71 - 1.84 * early if breaks == 2 else -1.4
        elif '\r' in token:
            value = -1.0
        elif any(c in lead for c in ';{}'):
            value = -0.9
        elif '?' in lead or '？' in lead:
            value = -0.35
        elif '.' in lead or '。' in lead:
            value = -0.41 - 0.60 * early
        elif lead and all(c in '-_=' for c in lead):
            value = -1.0
        elif lead.strip() and all(c in '()[] ' for c in lead):
            value = -0.67
        else:
            value = -0.55 - 0.12 * early if lead else -0.55
        heading = re.match(r'^(#{1,6})\s', line_start + lead)
        if heading and not lead.isspace():
            value = -0.07 * len(heading[1])
        if previous in ('<think>', '</think>') and not lead:
            value = -0.78
    elif token == ' \n':
        value = 0.10
    if token == '<|endoftext|>':
        line_start = ''
    elif '\n' in token:
        line_start = token.rsplit('\n', 1)[-1][:32]
    else:
        line_start = (line_start + token)[:32]
    return (doc, position + 1, line_start, token), float(value)

