"""Detect punctuation split across adjacent tokens.

Predict a negative activation when a punctuation-only token starts immediately
after punctuation at the end of the previous token. Opening delimiters and
escapes respond more strongly than closing delimiters and separators. Longer
merged chunks weaken the response; leading spaces suppress it. Bare line
breaks after punctuation have a smaller negative response.

Small exceptions cover TeX command pieces before braces, underscores after
letters, doubled backslashes, and the assistant header. Only the preceding
token is retained, and document boundaries clear that state.
"""
from math import log
import unicodedata

READS = ()

# Symbol class: characters, current-token strength, preceding-token strength.
SYMBOL_CLASSES = {
    'opening': ('([{<', -1.13, -0.84),
    'closing': (')]}>', -0.46, 0.0),
    'separator': (',.;:', -0.58, -0.34),
    'escape': ('\\', -1.16, -0.18),
    'slash': ('/', -1.19, -0.75),
    'quote': ('\'"“”‘’', -0.87, -0.42),
    'backtick': ('`', -0.48, -0.02),
    'underscore': ('_', -1.2, -0.15),
    'marker': ('#@', -1.22, -0.48),
    'dash': ('-−–—', -0.96, -0.36),
    'operator': ('+*=^|&~%', -0.87, -0.32),
    'dollar': ('$', -0.71, -0.08),
    'sentence': ('!?…', -0.6, -0.31),
    'wide': ('，。；：！？、（）「」『』《》【】～', -0.32, -0.07),
}


def strengths(character):
    for characters, current, previous in SYMBOL_CLASSES.values():
        if character in characters:
            return current, previous
    if unicodedata.category(character) == 'Sm':
        return (-0.18, 0.07)
    return None


def punctuation_piece(token):
    return bool(token) and all(strengths(c) or c.isspace() for c in token)


# Familiar pieces of TeX commands taking a brace-delimited argument.
TEX_GROUPING = {'frac', 'dfrac', 'tfrac', 'cfrac', 'boxed'}
TEX_ACCENTS_AND_ROOTS = {'hat', 'widehat', 'vec', 'sqrt'}
TEX_TYPE_STYLES = {'bb', 'bf', 'cal', 'mathrm', 'mathit', 'it'}
TEX_TEXT_ARGUMENTS = {'text', 'label', 'cite'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    value = 0.0
    if token == 'assistant' and previous == '<|im_start|>':
        value = -0.31
    elif token and previous and not previous.startswith('<|'):
        current = strengths(token[0])
        prior = strengths(previous[-1])
        if current and prior and punctuation_piece(token):
            size = sum(not c.isspace() for c in token)
            value = current[0] + prior[1] + 0.34 * log(size)
            value = min(0.0, value)
        elif token.isspace() and token[0] in '\r\n':
            if prior and punctuation_piece(previous):
                value = -0.46
        elif token == '{':
            if previous in TEX_GROUPING:
                value = 0.80
            elif previous in TEX_ACCENTS_AND_ROOTS:
                value = 0.54
            elif previous in TEX_TYPE_STYLES:
                value = 0.33
            elif previous in TEX_TEXT_ARGUMENTS:
                value = 0.15
            elif previous in {'begin', 'end'}:
                value = -0.20
        elif token == '_' and previous[-1].isalpha():
            value = 0.10 if len(previous.strip()) == 1 else 0.27
        elif token == '\\\\':
            value = -0.45
    return (document, token), float(value)

