"""Approximate a sparse response to adjacent punctuation and symbols.
When both the current and previous tokens are punctuation/symbol marks, return
a small negative value; common escape and code/comment marks get a stronger one.
"""
import unicodedata

READS = ()


CODE_MARKERS = {"\\", "\\\\", "#", "##", "//"}


def is_mark(token):
    marks = [ch for ch in token if not ch.isspace()]
    # U+FFFD can stand for an incomplete byte-level character, not a mark.
    return bool(marks) and all(
        ch != "\ufffd"
        and not ch.isalnum()
        and unicodedata.category(ch)[0] in "PS"
        for ch in marks
    )


def step(carry, prefix, upstream):
    if len(prefix.token_strings) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0

    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2]
    if is_mark(token) and is_mark(previous):
        if token in CODE_MARKERS:
            return None, -0.8
        return None, -0.15
    return None, 0.0

