"""A lexical approximation to a possession/self-reference signal.

Possessive and reflexive pronouns, `own`, `personal`, and code's `self` are
positive. Chinese/Japanese words for oneself are particularly strong. English
prepositions strengthen possessives; conjunctions and auxiliary verbs weaken
them. Capitalization and lack of leading whitespace modify the lexical signal.
Other tokens are zero, except weakly negative English nonpossessive pronouns.
The positive word classes summarize the high-importance training examples;
translations are grouped rather than given a separate coefficient for every word.
"""
READS = ()

ENGLISH = {
    'my': .8, 'your': .94, 'our': .98, 'his': 1.6, 'her': 1.04,
    'their': 1.63, 'its': 1.54, 'self': 1.28, 'own': 1.18,
    'personal': .75, 'personally': .59, 'whose': .53, 'thy': .51,
    'yours': .5, 'ours': .45, 'hers': .6, 'theirs': .6, 'mine': .1,
    'itself': 1.73, 'themselves': 1.84, 'ourselves': 2.33,
    'myself': 2., 'yourself': 2., 'himself': 2., 'herself': 2.,
    'yourselves': 2., 'oneself': 2., 'selfish': 1.1, 'selves': 1.55,
}
POSSESSIVES = {'my', 'your', 'our', 'his', 'her', 'their', 'its'}
ROMANCE = set('su sus sua suo seus tus loro leur leurs votre propio propia '
              'nuestro nuestra nuestros'.split())
GERMAN = set('seine seiner seinem seinen ihre ihrer ihrem ihren meiner'.split())
RUSSIAN_OWN = set('свой свои свою своей своего своим своих своими свое своем'.split())
EUROPEAN_POSSESSIVES = ROMANCE | GERMAN | RUSSIAN_OWN
PRONOUNS = {
    '我': 1.04, '你': .83, '您': .82, '他': .94, '她': .94, '它': .9,
    '其': 1.03, '我们': .8, '我們': .84, '他们': .75, '他們': .75,
    '它们': .78, '你们': .4, '你們': .5,
}
SELF_WORDS = {
    '自': .77, '己': 3.6, '自身': 2.2, '自身的': 2.4, '自我': 2.32,
    '自家': 2.07, '自行': 1.8, '各自': 1.45, '本人': 1.1, '本身': 1.1,
    '자신': 2.5, '자신의': 2.65, '나': .8, '우리': 1.05,
    'себя': 1.74, 'себе': 1.18, 'собой': .76, 'сам': .39, 'сами': .74,
    'selbst': .87, 'selber': 1.14, 'eigenen': 1.21, 'mình': 1.63,
}
PREPOSITIONS = set('of to for on from at about into during after before '
                   'between against behind in by with as through within under'.split())
CONJUNCTIONS = set('and or but that which what because'.split())
AUXILIARIES = set('is are was were be have has had'.split())


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = 0.
    if lower in ENGLISH:
        value = ENGLISH[lower]
        if word.istitle() and lower != 'self':
            value *= .5 if lower == 'my' else .7 if lower == 'our' else .8
        elif word.isupper():
            value *= .6
        if token == word and word.islower() and lower != 'self':
            value *= .3
    elif lower.lstrip('(<[:=/\t-') == 'self':
        value = 1.
    elif lower in ROMANCE:
        value = .65
    elif lower in GERMAN:
        value = .95
    elif lower in RUSSIAN_OWN:
        value = 2.48 if lower == 'свои' else .66 if lower == 'свой' else 1.5
    elif word in SELF_WORDS:
        value = SELF_WORDS[word]
    elif '自己' in word:
        value = 5.7 if word.endswith('的') else 6.3
        if word not in {'自己', '自己的'}:
            stem = word.removesuffix('的').removesuffix('自己')
            value = 3.6 if stem in PRONOUNS else 4.9
    elif word.startswith('自分'):
        value = 3.55 if word == '自分の' else 1.7
    elif word in PRONOUNS:
        value = PRONOUNS[word]
    elif not word.startswith(('其他', '尤其', '极其')):
        for pronoun, strength in PRONOUNS.items():
            if word.endswith(pronoun + '的'):
                value = strength + (.6 if pronoun in {'他', '她', '他们'} else .3)
                break
            if len(word) <= 5 and word.endswith(pronoun):
                value = .8 * strength
                break
    if lower in EUROPEAN_POSSESSIVES and token == word:
        value *= .15
    if token.startswith(' ') and lower in POSSESSIVES:
        prev = ''
        if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
            prev = prefix.token_strings[-2].strip()
