"""Possessive and "self" words, in several languages.

Unit 935 of layers.0.mlp.down_proj is a "one's own / refers back to oneself" detector.
It is quiet on most tokens, including "the", "of", and the English subject and object
pronouns (he, she, it, them). It fires on:
  - possessive determiners: their, his, its, her, your, our, my, whose, thy;
  - reflexives and self-words: myself, himself, themselves, itself, self, own, personal;
  - the Chinese reflexive 自己 ("oneself"), strongest, and 自身 / 自我 / 自分;
  - Chinese personal pronouns (我, 他, 她, 你, 您, 它, 我们), and them with 的 ("of"), e.g. 他的;
  - possessive-like words in other languages: свой/себя (Russian), ihre/seiner (German),
    su/sua (Spanish/Italian).
The possessive determiners count only as whole words (a leading space, or a capital), so
"our" inside "hour" or "four" stays at zero. Activation depends on the word alone, not
its surrounding context.
"""
READS = ()

# English words and their typical activation
ENGLISH = {
    "their": 1.6, "his": 1.6, "its": 1.5, "her": 1.0, "your": 0.9, "our": 0.9,
    "my": 0.8, "whose": 0.5, "thy": 0.5,
    "myself": 2.0, "yourself": 2.0, "himself": 2.0, "herself": 1.9,
    "ourselves": 2.3, "themselves": 1.8, "itself": 1.7,
    "self": 1.3, "own": 1.2, "personal": 0.7,
}
# Other languages
OTHER = {
    "自身": 2.1, "自我": 2.4, "自分": 2.5, "其": 1.0,
    "свои": 1.5, "себя": 1.8, "свой": 0.7, "своей": 1.6, "свою": 1.5,
    "ihre": 1.1, "ihrer": 1.0, "seiner": 1.1, "seine": 0.9,
    "su": 0.5, "sus": 0.75, "sua": 0.85, "suo": 0.7,
    "我": 1.0, "他": 0.9, "她": 1.0, "你": 0.8, "您": 0.9, "它": 1.0,
    "我们": 0.8, "他们": 0.76,
}
WEIGHTS = {**ENGLISH, **OTHER}


def activation(raw):
    if "自己" in raw:          # 自己 "oneself", and forms like 自己的, 给自己
        return 5.5
    word = raw.strip().lower().lstrip("(=/_.\"'")
    if word.endswith("的") and word[:-1] in OTHER:
        return 1.2             # Chinese pronoun + 的, e.g. 他的 "his"
    if word not in WEIGHTS:
        return 0.0
    # possessives must be whole words; reflexives also count inside code identifiers
    whole = raw[:1].isspace() or raw[:1].isupper() or not raw[:1].isascii() or raw[:1] in "(=/_.\"'"
    if whole or word.endswith("self") or word.endswith("selves") or word == "own":
        return WEIGHTS[word]
    return 0.0


def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

