wide punctuation and alphanumeric characters are weaker. Comment openers
also respond negatively. For ASCII parentheses, the preceding token's script,
word class and final character distinguish prose asides from grouping.

Only the previous token is kept, reset at document boundaries. Other tokens
receive zero: ordinary word-specific variation is deliberately not modeled.
"""
import unicodedata

READS = ()
LOGICAL_GROUPING = frozenset({'for', 'return', 'and', 'or'})
FUNCTION_WORDS = frozenset({
    'at', 'to', 'by', 'of', 'as', 'in', 'on', 'is', 'be', 'with',
    'a', 'an', 'from', 'that', 'the',
})
OPERATORS = '.:;,=+-*<>&|([/'
OPEN_BRACKETS = {'（': -2.62, '【': -2.20, '［': -1.80}
OPEN_QUOTES = frozenset('「『《')
CLOSE_QUOTES = frozenset('」』')
WIDE_MARKS = {
    '）': -0.20,
    '】': -0.38,
    '》': -0.42,
    '！': -0.41,
    '？': -0.30,
    '：': -0.18,
    '＜': -0.75,
    '＞': -0.65,
    '／': -0.62,
    '＠': -1.10,
    '＆': -0.87,
    '※': -0.55,
    '△': -0.22,
    '▼': -0.36,
    '・': -0.23,
    '～': -0.32,
    '〜': -0.39,
}

def punctuation_value(token):
    text = token.strip()
    if text.startswith(('/*', '<!--')):
        value = -0.48 if text.startswith('<!--') else -1.02
        if text.startswith('/**'):
            value += 0.25
        if token.startswith(' '):
            value -= 0.20 if text.startswith('/**') else 0.06
        if '\n' in token:
            value += 0.18
        return value
    if text == '(':
        return -0.24 if token.startswith(' ') else -0.06
    if len(text) == 1 and '０' <= text <= '９':
        return -0.70 if text == '０' else -0.55
    if len(text) == 1 and ('Ａ' <= text <= 'Ｚ' or 'ａ' <= text <= 'ｚ'):
        return -0.55
    if not text or '\n' in token:
        return 0.0
    if all(unicodedata.category(c)[0] in 'PS' for c in text):
        last = text[-1]
        if last in OPEN_BRACKETS:
            value = OPEN_BRACKETS[last]
        elif last in OPEN_QUOTES:
            value = -0.95
        elif last in CLOSE_QUOTES:
            value = -0.70
        elif last in WIDE_MARKS:
            value = WIDE_MARKS[last]
        elif text == '··':
            return -0.19
        else:
            return 0.0
        if len(text) > 1:
            value *= 0.83
        if token.startswith(' ') and (last in OPEN_BRACKETS or last in OPEN_QUOTES):
            value -= 0.45
        return value
    return 0.0

def parenthesis(previous, spaced):
    """Distinguish prose asides from conditional, logical and numeric grouping."""
    text = previous.strip()
    if not previous:
        return 0.08 if spaced else -0.17
    if any('\u3000' <= c <= '\u9fff' or '\uac00' <= c <= '\ud7a3'
           for c in text):
        return -0.63 if spaced else -0.68
    if text in {'if', 'while'}:
        return 0.12
    if not spaced:
        if text and (text[-1].isdigit() or text[-1] in OPERATORS):
            return 0.05
        return -0.05
    if text in LOGICAL_GROUPING:
        return 0.04
    if text in FUNCTION_WORDS:
        return -0.09
    if not text:
        return -0.12
    if text[-1].isdigit():
        return -0.24
    if text[-1] in "\"'”’`":
        return -0.38
    if text[-1] in OPERATORS:
        return -0.06
    return -0.31


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = punctuation_value(token)
    if token in (' (', '('):
        value = parenthesis(previous, token.startswith(' '))
    return (doc, token), float(value)

