programs.sol:
"""A ce-spelling detector, with stronger responses to short fragments.

The strongest negative response is to bare ce and short French demonstratives.
Short Cyrillic ц/це fragments are related triggers. Unspaced continuations
also count: c followed by an e-like token, or by another ce, increases the
negative response. Long fragments are weaker; common -ance/-ince endings
are discounted. This captures the main spelling pattern, not all lexical
variation in the component.
"""
import unicodedata

READS = ()
FRENCH_DEMONSTRATIVES = {
    'ces': -0.91,
    'cet': -0.76,
    'cette': -0.44,
    'cela': -0.09,
    'celle': 0.02,
    'celui': 0.13,
    'ceux': 0.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    text = prefix.token_strings[-1]
    raw = text.strip().lstrip('-_')
    s = raw.lower()
    n = len(s)
    boundary = text[:1].isspace()
    value = 0.0

    if s == 'ce':
        value = -1.46 - 0.52 * boundary
        if raw == 'Ce':
            value -= 0.33
        elif raw == 'CE':
            value += 0.05 + 0.35 * boundary
    elif s in FRENCH_DEMONSTRATIVES:
        value = FRENCH_DEMONSTRATIVES[s] - 0.35 * boundary
    elif s.startswith('ce'):
        value = -0.90 / (n - 1) - 0.07 * (n <= 4)
        if s.startswith('cen'):
            value += 0.65 / (n - 1)
        if s.startswith(('cel', 'cer')):
            value += 0.15 / (n - 1)
        if s.startswith('cell'):
            value += 0.26
        if s.startswith(('cea', 'cei', 'cee')):
            value -= 0.40
        value = min(value, 0.0)
    elif s == 'ace':
        value = -0.72
    elif s.startswith(('acet', 'procee')):
        value = -0.44
    elif s.startswith('conce'):
        value = -0.75 / (n - 4) ** 2
    elif s.startswith('cé'):
        value = -0.58 / (n - 1)
    elif s == 'ç':
        value = -0.31
    elif s == 'ц':
        value = -0.60 - 0.07 * boundary
    elif s.startswith('ц'):
        value = -(0.15 + 0.50 * s.startswith('це')) / (n - 1)
        if s.startswith('цеп'):
            value -= 0.54

    # Complete the spelling across an unspaced token boundary.
    joined = text.lower().lstrip("'’")
    p = previous.strip().lower()
    if p and joined and not boundary and joined[0].isalnum():
        first = unicodedata.normalize('NFD', joined[0])[0]
        if p.endswith('c'):
            if first == 'e' or first == 'æ':
                value -= 0.49 + 0.23 * (len(p) <= 2)
                if joined.startswith(('et', 'éd', 'è')):
                    value -= 0.49
                if text[:1].isupper():
                    value -= 0.07
                if len(joined) >= 5:
                    value += 0.31
            if joined.startswith(('ce', 'cs')):
                value -= 0.86 + 0.60 * (joined == 'ce')
        elif p.endswith('ц'):
            value -= 0.23 + 0.43 * (first in 'еэ')
            if len(p) == 1 and joined == 'е':
                value -= 0.96
        elif first in 'еэe' and p[-1] in 'скгčkч':
            value -= 0.34 if p[-1] in 'ск' else 0.15
        if first in 'еэe':
            if 'c' in p[-3:-1]:
                value -= 0.14
            if 'ц' in p[-3:-1]:
                value -= 0.28
        if joined in ('ce', 'ces') and p.endswith(
            ('an', 'in', 'en', 've', 'ble', 'í', 'á')
        ):
            value += 0.58
    return (doc, text), float(value)

