programs.sol:
"""Negative on edit-like spellings, rather than on editing intent.

The strongest training responses were on English editing words, identifier
fragments, and Chinese/Japanese editing characters. Inflection and case change the
strength. Compiling and administration words are weaker echoes of this signal.
A little signal persists onto word endings, 'the', 'of', 'by' and colons.
"""
READS = ()

EDIT_FORMS = {
    'edited': -2.9, 'editing': -3.8, 'edits': -2.5,
    'editable': -1.8, 'editorial': -1.5, 'editar': -3.4,
}
CHINESE = {
    '编': -6.5, '編': -6.3, '编辑': -6.4,
    '辑': -2.8, '輯': -2.8, '剪': -1.35,
    '小编': -3.25, '责任编辑': -2.7,
    '编写': -2.3, '编制': -2.3, '编程': -1.15, '编码': -0.95,
    '修改': -0.7, '审': -1.0, '审计': -0.7, '审批': -0.9,
}
FOLLOWING = {'the': 0.19, 'of': 0.30, 'by': 0.27, 'a': 0.06,
             ':': 0.13, '：': 0.13}
ENDINGS = frozenset(('or', 'ors', 'ial', 'ials', 'able', 'ed'))


def lexical(token):
    word = token.strip().lstrip('._/-(')
    lower = word.lower()
    spaced = token.startswith(' ')
    joined = token.startswith(('.', '_', '/', '-', '('))
    if lower == 'edit':
        if word.isupper():
            return -4.5
        if joined:
            return -4.2
        if word[0].isupper():
            return -5.3
        return -5.0 if spaced else -3.5
    if lower in ('editor', 'editors'):
        if token.startswith('.'):
            return -2.45
        if token.startswith('_'):
            return -2.87
        return -3.7 if spaced and word.islower() else -3.05
    if lower == 'editing' and word[0].isupper():
        return -2.6
    if lower in EDIT_FORMS:
        return EDIT_FORMS[lower]
    if lower == 'admin':
        return -1.15 if joined or word[0].isupper() else -1.63
    if lower.startswith('administ'):
        return -0.5
    if lower.startswith('compil'):
        return -0.9 if spaced else -0.4
    if lower in ('едак', 'редак'):
        return -1.95
    return CHINESE.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, last = (0.0, '')
    if carry is not None and carry[0] == doc:
        previous, last = carry[1:]
    value = lexical(token)
    # Read joined text only when a token contains incomplete Unicode bytes.
    if '\ufffd' in token and carry is not None and carry[0] == doc:
        char = prefix.text_prefixes[-1][-1:]
        if char in ('编', '編', '辑', '輯'):
            token = char
            value = -8.8 if char == '编' else CHINESE[char]
    cue = value
    if value == 0.0 and previous < -2.0:
        value = previous * FOLLOWING.get(token.strip().lower(), 0.0)
        if token.lower() in ENDINGS:
            value = previous * 0.3
    if last in ('編', '编') and token in ('輯', '辑', '集', '译', '碼'):
        value = -4.7 if token in ('輯', '辑') else -1.25
    if token == 'edit' and last.endswith('['):
        value = -5.3
    return (doc, cue, token), float(value)

