            value = -4.41 if body == 'E' else -2.35
        elif token == 'e' and previous[-1:].isalpha():
            value = -0.33
        elif token == 'E' and previous[-1:].isupper():
            value = -0.70
        elif token.startswith('.'):
            value = -1.50 if body == 'E' else -0.94
        elif body == 'E':
