            else:
                value = -1.31
        else:
            value = -1.56 if not boundary else -1.44
    elif body in ('é', 'É'):
        value = -0.77 if boundary else -0.45 if body.isupper() else -0.03
    elif body in ('ε', 'Ε', 'е', 'Е'):
        value = -0.65 if boundary else -0.40 if body.isupper() else -0.06
    elif body in ('э', 'Э', 'え', 'エ'):
        value = -0.93
    elif low.startswith(('econ', 'conom', 'эконом')) or body == '经济':
        value = -1.18
    elif low.startswith(('elect', 'элект')) or body in ('电', '電'):
        value = -0.86
    elif low.startswith('emiss'):
        value = -0.65
    elif low.startswith('equat'):
        value = -0.30
    elif low.startswith('e'):
