"""Approximate a technical-symbol response, strongest for a single backslash.

Token-final backslashes receive large positive values, unlike written-out
escapes. Their immediate punctuation/line context adjusts the strength;
document starts weaken it. Math/markup symbols and the C++ words std/const
get smaller values. Unicode fragments respond when a character remains
unfinished, but not when it is completed; the recent character script can
suppress new-fragment responses. Other tokens default to zero. Numerical levels were
estimated from training activations, not from the model's weights.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ""
    start = carry is None or carry[0] != doc
    word = s.strip()
    spaced = s.startswith(" ")
    value = 0.0

    if "\\" in s and s.endswith("\n"):
        value = 1.2
    elif word.endswith("\\"):
        if word == "\\":
            value = 2.65 if spaced else 2.3
            if start:
                value = 0.85
            elif prev.rstrip().endswith("\\"):
                value = 1.0
            elif prev.endswith("\n"):
                value += 1.0
            elif not spaced and prev.rstrip()[-1:].isalpha():
                value -= 0.5
            if spaced and prev.rstrip().endswith("*"):
                value += 1.8
            elif not spaced and not prev.endswith("\n"):
                if "\\" in prev or '"' in prev:
                    value -= 0.4  # Escaped text / quoted-string endings.
                elif prev.rstrip().endswith("$$"):
                    value += 0.6  # Display-math boundary.
        elif word.count("\\") > 1:
            value = 0.38
        elif word[-2] in "\"'":
            value = 1.55
        else:
            value = 0.95
            if word[-2] in "({.:" and not spaced:
                value = 0.78
    elif "\\" in word:
        if word.startswith("\\x"):
            value = 0.2
        elif word[-1:] in "$<%_":
            value = 0.7
        elif word[-1:] in "([":
            value = 0.3
        elif word[-1:] in "\"nt":
            value = -0.08
    elif word.startswith("/*") or word.endswith("*/"):
        value = 0.15 if word.startswith("/*") else 0.0
    elif word.count("*") == 1:
        if word == "*":
            value = 0.7 if spaced else 0.61
            if spaced and (prev.isspace() or prev.endswith("\n")):
                value = 0.12
        else:
            value = 0.42
    elif word.count("$") == 1 and word.endswith("$"):
        if word == "$":
            value = 0.23 if spaced else 0.04
            if prev.isspace() or prev.endswith("\n"):
                value = 0.6
        elif word[-2] not in ")}]":
            value = 0.55
    elif word.count("<") == 1 and not word.endswith(">") and "=" not in word:
        value = 0.55
    elif word == ">":
        value = 0.51 if spaced else 0.07
        if prev.isspace() or prev.endswith("\n"):
            value = 0.35
    elif word.endswith("^") and word.count("^") == 1:
        value = 0.28 if word[:-1].endswith((")", "]")) else 0.5
    elif word.endswith("%"):
        value = 0.58 if spaced else 0.23
    elif word == "@":
        value = 0.88 if spaced else 0.52
    elif word and set(word) == {"#"} and len(word) >= 3:
        value = 0.58 if len(word) == 3 else 0.42
    elif word == "•":
        value = 0.44
    elif "�" in s:
        # Decode only these rare byte-fragment positions, not every prefix.
        text = s if start else prefix.text_prefixes[-1]
        old = prefix.text_prefixes[-2] if not start else ""
        if not text.endswith("�"):
            value = -0.05  # This token completed a character.
        elif old.endswith("�"):
            value = 1.13  # Adjacent fragments still leave a character unfinished.
        else:
            recent = text.rstrip("�")[-12:]
            letters = [c for c in recent if ord(c) > 127 and not c.isspace()]
            name = unicodedata.name(letters[-1], "") if letters else ""
            if name.startswith(("CJK", "HANGUL", "HIRAGANA", "IDEOGRAPHIC",
                                "FULLWIDTH")):
                value = 0.0
            elif spaced and name.startswith("GREEK"):
                value = 0.85
            else:
                value = 0.6
    elif word == "std":
        value = 0.85
    elif word == "const":
        value = 0.5
    return (doc, s), float(value)

