"""Predict a small token cue: strongest for backslashes, smaller for
replacement-decoded fragments and Unicode punctuation or symbols."""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "\\" in token:
        value = 2.2
    elif token.startswith(" ") and "�" in token:
        value = 0.85
    elif "�" in token:
        value = 0.2
    elif any(unicodedata.category(ch)[0] in "PS" for ch in token):
        value = 0.25
    else:
        value = 0.0
    return None, 0.36 * value

programs.sol:
"""Sparse lexical model of writing, depiction, and expressive style.

Chinese literary terms and English depiction/style words give negative values.
Recent artistic vocabulary strengthens writing words; its cue fades by 10%
per token and resets between documents. Split word endings and a few Chinese compounds continue the response.
Small secondary rules cover quantifiers and visible formatting. This leaves
most of the component's diffuse, token-specific variation unexplained.
"""
import re

READS = ()
DEPICTION = re.compile(r'^(depict|portray|narrat|recount|evoke|chron)')
STYLE = re.compile(r'^(vivid|stylist|graceful|majestic|descriptive|eloquen|lyrical)')
COMPLETED = {'depicted', 'portrayed', 'conveyed', 'conveying', 'captured'}
CONVEY = {'convey', 'conveys', 'capturing', 'captures'}
WRITING = {'write', 'writes', 'writer', 'writers', 'writing', 'written'}
ART = set('''song songs poem poems poetry prose literary novel art artistic
paintings essay creative 诗 詩 散文 小说 小說 文学 文學 修辞 修辭'''.split())

# Literal word families, with one response per named concept.
CLASSES = {
    'literary_rhetoric': (-0.67, '抒 题材 題材 娓'),
    'Chinese_narration': (-0.56, '描写 描寫 描绘 描繪 叙事 敘事'),
    'composition_technique': (-0.22, '手法 技法 技巧 构思 構思'),
    'drawing': (-0.34, '描'),
    'Chinese_writing': (-0.16, '写 寫 写的 写了'),
    'pen_and_drawing': (-0.13, '笔 筆 绘 繪'),
    'Chinese_expression': (-0.17, '描述 表达 表達 创作 創作 塑造 展现 展現'),
    'authors': (-0.07, 'writer writers'),
    'writing_forms': (-0.04, 'written writing writes'),
    'description_nouns': (-0.03, 'description descriptions'),
    'describe_verbs': (-0.05, 'describe describes described describing'),
    'emotions': (-0.13, 'emotion emotions emotional emotionally'),
    'creative_media': (-0.12, 'medium documentary comic themes lyrics'),
    'pictorial_activity': (-0.10, 'capture paint painted painter'),
    'quantity_determiners': (-0.04, 'all each every some few'),
    'free_choice_or_absence': (0.02, 'any either no'),
    'plural_demonstratives': (0.04, 'these those'),
    'past_action_forms': (0.05, 'said seen found used made played won'),
}
CLASSES = {name: (weight, frozenset(words.split()))
           for name, (weight, words) in CLASSES.items()}
CHINESE_WRITE = CLASSES['Chinese_writing'][1]
CHINESE_DESCRIPTION = (CLASSES['Chinese_narration'][1]
                       | CLASSES['Chinese_expression'][1]
                       | CHINESE_WRITE | {'描', '绘', '繪'})


def description_word(word):
    return bool(DEPICTION.match(word) or STYLE.match(word)) or word in (
        CONVEY | COMPLETED | {'description', 'descriptions'}
    ) or word in CHINESE_DESCRIPTION


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, art = '', 0.0
    else:
        _, previous, art = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = sum(weight for weight, words in CLASSES.values() if word in words)
    if word in COMPLETED:
        value -= 0.12
    elif DEPICTION.match(word):
        value -= 0.20
    if STYLE.match(word):
        value -= 0.24
    if word in CONVEY:
        value -= 0.27

    if word == 'of' and description_word(previous):
        value -= 0.12
    if (word in {'the', 'a', 'in', 'by', '了', '的', '的是'}
            and (description_word(previous) or previous in WRITING)):
        value -= 0.036
    if word in {'ly', 'ling', 'icles', 'ing'} and description_word(previous):
        value -= 0.40
    if word == '手法' and previous in {'辞', '辭', '修辞', '修辭'}:
        value -= 0.77
    if word in WRITING:
        value -= 0.22 * art
    if word in CHINESE_WRITE or word == '描':
        value -= 0.34 * art
    if word == 'writing' and previous == 'in':
        value += 0.09
    if previous == '描' and word in {'写', '寫', '绘', '繪'}:
        value -= 0.35
    if (previous, word) in {('抒', '发'), ('娓', '道')}:
        value -= 0.65

    if word in {'<tool_response>', '</tool_response>', '<think>'}:
        value += 0.09
    if token == '\r':
        value += 0.15
    if word == 'www':
        value += 0.14
    if len(word) >= 5 and set(word) <= {'-', '_'}:
        value += 0.08

    art *= 0.9
    if (word in ART or word in CONVEY or STYLE.match(word)
            or (DEPICTION.match(word) and word not in COMPLETED)
            or word in CLASSES['literary_rhetoric'][1]
            | CLASSES['Chinese_narration'][1] | {'描'}
            or (word in {'辞', '辭'} and previous == '修')):
        art = 1.0
    return (doc, word, art), float(value)

"""Recognize lexical markers of temporal order, source, and range.

'Before' is the dominant signal; 'prior to' is another precedence marker.
Other relational words give weaker responses. 'Between' is weaker after
comparison or relationship nouns. A small part of the temporal signal
continues onto following articles and pronouns. State resets at document
boundaries; unrecognized tokens return zero.
"""
READS = ()

RELATION_WORDS = {
    'after': 1.05, 'until': 1.05, 'prior': 1.0,
    'from': 0.57, 'during': 0.69, 'without': 0.63,
    'between': 0.27, 'instead': 0.46, 'pre': 0.35,
    'till': 0.39, 'than': 0.10,
}

# Common equivalents of "before", "after", and "from".
TRANSLATIONS = {
    'antes': 1.8,       # Spanish: before
    'bevor': 3.1,       # German: before
    'avant': 1.2,       # French: before
    'prima': 0.73,      # Italian: before
    'перед': 0.78,      # Russian: before
    'trước': 1.08,      # Vietnamese: before
    'belum': 4.8,       # Indonesian: not yet; suffix of sebelum, before
    '前に': 0.35,        # Japanese: before
    'после': 0.7,       # Russian: after
    'بعد': 1.08,        # Arabic: after
    'до': 0.43,         # Russian: until
    'desde': 0.34,      # Spanish: from/since
}


# Nouns naming a relationship or a quantity measured between two entities.
RELATION_NOUNS = frozenset({
    'relationship', 'relationships', 'relation', 'association', 'correlation',
    'interaction', 'interactions', 'link', 'connection', 'connections',
    'overlap', 'correspondence', 'synergy', 'ratio',
    'difference', 'differences', 'distinction', 'comparison', 'match',
    'distance', 'angle', 'gap',
})
REFERENTS = frozenset({
    'i', 'you', 'we', 'he', 'she', 'it', 'they', 'us', 'a', 'an', 'this', 'that',
})


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    text = raw.strip().lstrip('._/(:@-')
    word = text.lower()
    doc = int(prefix.document_ids[-1])
    previous, capitalized = ('', False)
    if carry is not None and carry[0] == doc:
        previous, capitalized = carry[1:]

    if word == 'before':
        value = 7.6 if raw == 'Before' else 6.5
        if previous in {'as', 'never', 'than'}:
            value = 5.4
        if raw.lstrip().startswith('@'):
            value = 3.8
    elif word in {'beforeeach', 'beforeall'}:
        value = 3.8
    elif word == 'to' and previous == 'prior':
        value = 3.6
    elif word == 'of' and previous == 'instead':
        value = 0.65
    elif word == 'between':
        value = 0.52
        if previous in RELATION_NOUNS:
            value = -0.12
        elif previous == 'in':
            value = 0.85
        elif text[:1].isupper():
            value = 0.74
    elif word == 'from':
        value = 0.57
        if not raw[:1].isspace() or text[:1].isupper():
            value = 0.73
        if text.isupper():
            value = 0.47
    elif word == 'the' and previous == 'before':
        value = 1.3 + 0.4 * capitalized
    elif previous == 'before' and word in REFERENTS:
        value = 0.6
    elif word == 'the' and previous in {'after', 'during', 'until'}:
        value = (0.38 if previous == 'after' else 0.24) + 0.2 * capitalized
    elif word in {'在', '从', '從', '，在'}:
        value = 0.68
    else:
        value = RELATION_WORDS.get(word, TRANSLATIONS.get(word, 0.0))
    return (doc, word, text[:1].isupper()), value

programs.luna:
"""Mark English relational prepositions for origin, interval, and earlier time."""

READS = ()

SOURCE = {"from"}
INTERVAL = {"between", "during"}
EARLIER = {"since", "prior", "before"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(".,:;!?()[]{}\"'")
    if word == "before":
        return None, 6.5
    if word in SOURCE | INTERVAL | EARLIER:
        return None, 0.6
    return None, 0.0

programs.sol:
"""Detect word-like chunks attached to abbreviated prefixes.

A capitalized name after a single letter (C + Item), or an underscore field
after a consonant abbreviation, receives a large positive response. Basic data
and I/O words count as words even in lowercase; ordinary word fragments do
not. The response is a word-shape amplitude times an abbreviation strength,
plus a small word-shape baseline. Longer ordinary words and actual whitespace
usually suppress the response. Acronym-led compounds are weaker.
The only state is the previous token, reset at each document boundary.
"""
import re

READS = ()

# Basic data/container names and common input/output operations.
DATA_WORDS = set('''
data text file path type name value key size source target state status count
number length error errors info log config configuration options result record
entry list array tree table node object stream buffer context field property
process user client server request response message string date time format
print read write parse load save import
'''.split())
FUNCTION_WORDS = set('''
the a an of to in on by for with at from and or not no if else while where
when this that these those there some any all each it its as be is are was
were has have had do does did can may must will would should into upon
get set new run try int let var
'''.split())
ABBREVIATIONS = set('''
api cpu css csv db dna fs gl gpu html http id io ip js json kv msg os pdf
php ptr qt ram ref rgb rna rpc sdk sql ssl std svg tcp tls tmp ts ui uri
url utf uuid wx xml
'''.split())

WORD_END = re.compile(r'[A-Za-z]+$')
MORPHOLOGICAL_PREFIXES = set('''
re un non dis de pre post pro con com sub super inter intra trans anti auto
semi over under out in im mis ex en per co
'''.split())
FAMILIAR_WORDS = DATA_WORDS | ABBREVIATIONS
ORDINARY_STEMS = FUNCTION_WORDS | MORPHOLOGICAL_PREFIXES


def familiar_word(word):
    word = word.lower()
    return (word in FAMILIAR_WORDS
            or (word.endswith('s') and word[:-1] in DATA_WORDS)
            or (word.endswith('ies') and word[:-3] + 'y' in DATA_WORDS))


def abbreviation_strength(previous):
    match = WORD_END.search(previous)
    tail = match.group() if match else ''
    if match and match.start() and previous[match.start() - 1].isalpha():
        return 0.03  # Do not mistake part of a non-ASCII word for an initial.
    if not tail:
        return 0.59 if previous[-1:].isdigit() else 0.0
    if previous in ('\\n', '\\t', '\\r'):
        return 0.25
    n = len(tail)
    if n == 1:
        return 1.0 if len(previous) == 1 else 1.27
    if not any(c.lower() in 'aeiou' for c in tail):
        return 0.78 if n <= 3 else 0.42
    if tail.isupper() and n <= 5:
        return 0.35
    if tail.lower() in ABBREVIATIONS:
        return 0.40
    if (n <= 3 and not familiar_word(tail)
            and tail.lower() not in ORDINARY_STEMS):
        return 0.33
    if tail[-1].isupper() and tail[-2].islower():
        return 0.80  # A final capital can itself be a name prefix.
    return 0.03


def word_shape(s):
    # Return a baseline and an amplitude, shared by all words of this shape.
    if s.startswith('_'):
        word = s.lstrip('_')
        if word and not (word.isascii() and word.isalpha()):
            return 0.0, 0.0
        return (-0.025, 0.21) if len(s) <= 3 else (0.04, 0.79)
    if s.startswith('-'):
        if not (s[1:].isascii() and s[1:].isalpha()):
            return 0.0, 0.0
        return (-0.02, 0.40) if len(s) >= 4 else (0.0, 0.0)
    if not (s.isascii() and s.isalpha()):
        return 0.0, 0.0
    if len(s) == 1:
        return 0.0, -0.03
    if s.isupper():
        if len(s) >= 3 and familiar_word(s):
            return -0.085, 0.59
        return -0.04, 0.05
    if s[0].isupper():
        if s[1].isupper():
            return -0.02, 0.30  # An acronym-led compound is not a fresh word.
        if len(s) == 2:
            return 0.0, 0.36
        return -0.03, (1.10 if len(s) <= 4 else 1.35)
    if familiar_word(s):
        return (-0.04, 0.11) if len(s) <= 3 else (-0.005, 0.83)
    return -0.01, 0.02


def predict_piece(s, previous):
    baseline, amplitude = word_shape(s)
    return baseline + amplitude * abbreviation_strength(previous)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, s), float(predict_piece(s, previous))

programs.luna:
"""A sparse cue for the word family around power and authority.

The strongest responses are on "power" forms. Smaller cues cover rights,
authority, and mathematical powers; the spelling fragment "ower" also catches
some split tokens.
"""

READS = ()

RELATED_WORDS = (
    "author", "authorisation", "authorization", "authorised", "authorized",
    "sovereign", "privilege", "permission", "rights", "copyright", "royalty",
    "ponent", "weight", "watt", "potent", "poder",
    "實力", "实力", "力量", "能量",
)

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()

    if "powerful" in token:
        return None, -3.3
    if "power" in token:
        return None, -4.8
    if "ower" in token:
        return None, -3.5
    if "authority" in token:
        return None, -2.5
    if token.strip() == "权":
        return None, -6.0
    if "权" in token or "權" in token:
        return None, -4.5
    if token.lstrip().startswith("pow"):
        return None, -0.9
    if any(word in token for word in RELATED_WORDS):
        return None, -1.3
    return None, 0.0

programs.sol:
"""Approximate a Russian/Soviet lexical and Slavic-name spelling signal.

Listed Russia-associated names, places, vocabulary and country domain
endings get large negative values. The vocabulary sets are strength groups,
not exhaustive word classes.
Listed Latin-letter name fragments get smaller negative values, sometimes
strengthened by the preceding spelling of the unfinished word. These rules
also fire in unrelated words sharing those fragments. Other tokens are
neutral, except the positive false friend cov- (as in covariance).
The unfinished word is cleared at word and document boundaries.
"""
import re

READS = ()

CORE_RUSSIAN_TERMS = {'Moscow', 'Putin', 'Bolshevik', '莫斯科'}
DIRECT_RUSSIAN_TERMS = {
    'Russia', 'Russian', 'Soviet', 'USSR', 'Lenin', 'Vladimir',
    'Mikhail', 'ikhail', 'Dmit', 'Dmitry', 'Sergei', 'Sergey',
    'Kiev', 'russian', '-Russian', '俄', '俄罗斯', '俄国', '普京',
    'روسي', 'الروسي', 'روسيا',
}
RUSSIA_AND_NEIGHBOR_TERMS = {
    'Ukraine', 'Ukrainian', 'Ukrain', 'kraine', 'Belarus', 'Nikol',
    'Siber', 'Kyiv', 'Soviets', 'Russians', 'Petersburg', 'Kremlin',
    'Kazakhstan', 'akhstan', 'Uzbek', 'rgyz', 'Donetsk', '苏联', '中俄',
}
RUSSIAN_ASSOCIATIONS = {
    'Ivan', 'Yuri', 'Boris', 'Stalin', 'Dmitri', 'Igor',
    'Crimea', 'vodka', 'odka', '乌克兰', 'Владимир',
}

REGIONAL_ASSOCIATIONS = {
    'Orthodox', 'Azerbaijan', 'Azerbai', 'Lithuania', 'Latvia', 'Bulgarian',
    'Mongolia', 'Viktor', 'Cyril', 'Aleks', 'Sasha', 'Nikon',
    'russ', 'russe', 'Russ', 'Kh', 'Zh', 'Obl',
}
RELATED_PLACES_AND_NAMES = {
    'Alexander', 'Alexand', 'Petro', 'Serbia', 'Serbian', 'Bulgaria',
    'Georgian', 'Croatia', 'Croatian', 'Yugoslavia', 'Estonia',
}

# Latin transliterations of name endings, grouped by their response strength.
ENDINGS = (
    ({'ovich'}, -3.8),
    ({'kov', 'akov', 'sky', 'insky', 'insk', 'enko', 'ovsky', 'tsky',
      'lya'}, -2.0),
    ({'sov', 'aya', 'iev', 'nik', 'kh', 'akh', 'ikh', 'hev', 'imir',
      'gor', 'arov', 'egov', 'ansk', 'ograd', 'avic', 'iya', 'asily'}, -1.3),
    ({'ov', 'ev', 'ko', 'ya', 'ky', 'ny', 'zh', 'vo', 'ovic', 'eva',
      'ussia', 'ussian', 'andr', 'ovi', 'lov', 'rov', 'inski'}, -0.8),
    ({'ova', 'ski', 'sk', 'ich', 'oy', 'chn', 'ii', 'va', 'ka', 'iy',
      'uki', 'ye', 'kie', 'ych', 'yy', 'ogo', 'ovo', 'nov', 'nya',
      'burg', 'grad', 'vy'}, -0.5),
    ({'iv', 'v', 'ian', 'ina', 'av', 'ki', 'no', 'na', 'ja', 'je',
      'ch', 'sh', 'ry', 'y', 'k'}, -0.2),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    stem = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    if word in CORE_RUSSIAN_TERMS:
        value = -4.0
    elif word in DIRECT_RUSSIAN_TERMS:
        value = -3.2
    elif word in RUSSIA_AND_NEIGHBOR_TERMS:
        value = -2.6
    elif word in RUSSIAN_ASSOCIATIONS:
        value = -1.8
    elif word in REGIONAL_ASSOCIATIONS:
        value = -1.15
    elif word in RELATED_PLACES_AND_NAMES:
        value = -0.8
    elif word in {'.ru', '.ua'}:
        value = -2.2
    else:
        value = 0.0
        for endings, response in ENDINGS:
            if token in endings:
                value = response
                break
        lower = stem.lower()
        if token == 'ov':
            if lower.endswith(('ik', 'an', 'un', 'yn', 'kh')):
                value = -2.0
            elif lower.endswith(('en', 'ol', 'il', 'or', 'rn')):
                value = -1.3
            elif lower.endswith('c'):
                value = 1.1  # cov-, as in covariance, is a false friend.
            elif not stem:
                value = -0.2
        elif token == 'ev' and lower.endswith('y'):
            value = -1.9
        elif token in {'ich', 'sk', 'sky', 'aya', 'ii'}:
            if lower.endswith(('ov', 'ev', 'sk')):
                value = -2.8 if token == 'sky' else value - 1.25
            elif token in {'ich', 'sk'}:
                value = -0.2
        elif token == 'chen':
            value = -1.3 if lower.endswith(('sh', 'v')) else -0.15
        elif token == 'iv' and lower in {'ky', 'lv'}:
            value = -2.3
        elif token == 'iv' and lower.endswith(('av', 'zh')):
            value = -1.5
        elif token == 'ian' and lower.endswith('russ'):
            value = -2.0
    tail = re.search(r'[A-Za-z]+$', stem + token)
    new_stem = tail.group()[-48:] if tail else ''
    return (doc, new_stem), value

programs.luna:
"""Flag selected proper words and capitalized words with Slavic surname endings."""
READS = ()

SURNAME_ENDINGS = (
    "sky", "ski", "ska", "ský", "skij", "skiy", "kov", "ov",
    "ova", "ev", "eva", "ovich", "evich", "vich", "enko", "yuk",
)

PROPER_NAME_WORDS = {
    "ukraine", "poland", "soviet", "yuri", "nikolai", "herzliya",
    "ryoichi", "natsuki", "aviv",
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, capitalized = "", False
    else:
        _, word, capitalized = carry

    pieces = []
    piece = ""
    for ch in raw:
        if ch.isalpha():
            piece += ch
        elif piece:
            pieces.append(piece)
            piece = ""
    if piece:
        pieces.append(piece)

    if not pieces:
        return (doc, "", False), 0.0

    starts_word = not raw[:1].isalpha()
    if len(pieces) > 1:
        word = pieces[-1]
        capitalized = pieces[-1][:1].isupper()
    elif starts_word or not word:
        word = pieces[0]
        capitalized = pieces[0][:1].isupper()
    else:
        word += pieces[0]

    value = 0.0
    if raw[-1:].isalpha() and capitalized:
        lower = word.lower()
        if lower in PROPER_NAME_WORDS:
            value = -0.8
        elif any(len(lower) >= len(end) + 2 and lower.endswith(end)
                 for end in SURNAME_ENDINGS):
            value = -0.8
    return (doc, word[-32:], capitalized), value

programs.sol:
"""A lexical signal for questions, uncertainty, and reasoning.

Question words give large pulses; related vocabulary gives smaller ones.
For English 'question(s)', a few local cues adjust the pulse: a definite
article strengthens it, while nearby asking or answering words weaken it.
This is not a sentence-level question detector: a plain '?' gives zero.
Only the current token and up to five preceding tokens are read.
"""
READS = ()

# Word families share a scale, rather than storing arbitrary token IDs.
DOUBT = set('doubt doubts wonder ponder'.split())
INQUIRY = set('ask asks asked asking inquire inquiry inquiries debate debates'.split())
REASONING = set('answer answers result results query queries please unknown '
                'discussion interesting considered confusion issue issues subjects '
                'problem topic topics'.split())
REFLECTION = set('consider considering consideration considerations difficult '
                 'interest interests conclusion conclusions examples worth '
                 'claim claims determination request requests requested '
                 'concern concerns curious uncertain uncertainties uncertainty '
                 'doubtful doubted mysterious suspicion suspicious'.split())


def lexical_pulse(raw):
    word = raw.strip().strip('_./-()[]').lower()
    if word in {'question', 'questions'}:
        if word == 'question':
            return 6.1 if raw.strip().isupper() else (
                7.6 if raw.strip()[:1].isupper() else 6.45)
        return 4.65 if raw.strip()[:1].isupper() else 5.4
    if word in {'questioned', 'questioning'}:
        return 5.1
    if word == 'questionable':
        return 3.1
    if word in {'questionnaire', 'questionnaires'}:
        return 1.85
    # Tokenized pieces of question words in English and Spanish.
    if word == 'uestion':
        return 4.0
    if word == 'unquestion' or (word == 'ques' and raw.startswith(' ')):
        return 2.55
    if word in {'regunta', 'reguntas', 'untas'}:
        return 3.5
    if word in {'pregunta', 'preguntas'}:
        return 2.7
    # Question vocabulary: German, Russian, Chinese/Japanese, and Korean.
    if raw.strip() == 'Frage':
        return 5.4
    if raw.strip() == 'Fragen':
        return 3.0
    if word == 'вопрос':
        return 3.35
    if word.startswith('вопрос'):
        return 2.6
    if word == '疑问':
        return 3.9
    if word in {'疑惑', '怀疑', '质疑', '问答', '提问', '질문'}:
        return 2.5
    if word in {'问题', '問題', '问'}:
        return 2.2
    if '问题' in word or word in {'問', '疑'}:
        return 1.8
    if word == 'wondering':
        return 2.8
    if word in {'wondered', 'wonders'}:
        return 1.55
    if word in DOUBT:
        return 1.9 if raw.startswith(' ') else 0.5
    if word == '¿':
        return 0.65
    if word == 'example':
        return 0.45 if raw.strip()[:1].isupper() else 0.1
    if word in {'matter', 'exercise', 'challenge', 'challenges'}:
        return 0.35
    if word in {'subject', 'mystery'}:
        return 1.05
    if word in INQUIRY:
        return 1.05 if raw.startswith(' ') else 0.65
    if word in REASONING:
        return 0.75
    if word in REFLECTION or word in {'resulting', 'resulted', 'problems'}:
        return 0.55
    if word in {'请', '請', '结果', '結果', '回答'}:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    value = lexical_pulse(raw)
    if raw.strip().lower() not in {'question', 'questions'}:
        return None, float(value)

    # Read only a short, same-document context, so packing cannot leak state.
    t = prefix.position
    doc = prefix.document_ids[-1]
    previous = [prefix.token_strings[i] for i in range(max(0, t - 5), t)
                if prefix.document_ids[i] == doc]
    if not previous:
        return None, float(value + 0.9)
    near = {s.strip().lower() for s in previous}
    last = previous[-1].strip()
    if last == 'the':
        value += 0.65
    elif last in {'The', 'THE'}:
        value += 1.35
    elif last.lower() in {'this', 'your', 'that'}:
        value -= 0.3
    elif last.lower() == 'trick':
        value -= 1.7
    elif last.lower() in {'related', 'similar'}:
        value -= 2.0
    if near & {'ask', 'asks', 'asked', 'asking'}:
        value -= 0.8
    if near & {'answer', 'answers', 'answered', 'answering'}:
        value -= 0.85
    if near & {'test', 'choice', 'homework', 'exam'}:
        value -= 1.2
    if '\n' in previous[-1]:
        value -= 0.45
    return None, float(value)

programs.haiku:
"""Question-word detector.

This MLP feature (layer 0, one of the MLP's 'down_proj' rank-one pieces) reads the current
token only. It writes a strong signal when the token is the word "question" (or
"questions", "Question", "questioned", ...), a medium one for the same idea in other
languages, and a weak one for nearby words about doubt, asking, problems and results.
Everything else is about zero.
"""

READS = ()

# Activation levels, from the data: mean activation on each family of tokens.
QUESTION_LEVEL = 6.0
TRANSLATION_LEVEL = 2.5
RELATED_LEVEL = 1.0

TRANSLATIONS = {"вопрос", "вопросы", "问题", "問題", "的问题", "问", "問", "问答", "询问"}
RELATED = {
    "doubt", "doubts", "wonder", "wondered", "wondering", "wonders", "ask", "asked",
    "asking", "asks", "query", "inquiry", "inquire", "problem", "problems", "issue",
    "issues", "answer", "result", "results", "subject", "mystery", "uncertainty",
    "unknown", "debate", "topic", "difficult", "consider", "considered", "interest",
}


def word_value(token: str) -> float:
    word = token.strip().lower()
    if word.startswith("question") and not word.startswith("questionn"):
        return QUESTION_LEVEL
    if word == "frage":
        return QUESTION_LEVEL
    if word in TRANSLATIONS:
        return TRANSLATION_LEVEL
    if word in RELATED:
        return RELATED_LEVEL
    return 0.0


def step(carry, prefix, upstream):
    return None, word_value(prefix.token_strings[-1])

programs.luna:
"""A question is the strongest clear cue. Related problem-and-answer
vocabulary gets a small positive guess; unrelated tokens get zero."""

READS = ()

QUESTION_WORD = "question"
RELATED_WORDS = frozenset({
    "problem", "problems", "issue", "issues", "answer", "answers",
    "solution", "solutions", "result", "results", "example", "examples",
    "clue", "clues",
})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(".,!?;:()[]{}<>\"'`").casefold()
    if word == QUESTION_WORD:
        return None, 6.5
    if word in RELATED_WORDS:
        return None, 0.55
    return None, 0.0
